import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';class FavoritesScreen extends StatelessWidget{const FavoritesScreen({super.key});@override Widget build(BuildContext c){final u=FirebaseAuth.instance.currentUser!.uid;return Scaffold(appBar:AppBar(title:const Text('Favorit')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('users').doc(u).collection('favorites').snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.docs.isEmpty)return const Center(child:Text('Belum ada favorit'));return ListView(children:s.data!.docs.map((d)=>ListTile(title:Text(d.data()['title']??'Iklan'),subtitle:Text('Rp '+(d.data()['price']??0).toString()))).toList());}));}}